-- Final source: doc/数据采集改造1008/3、满意度及投诉服务体验.xlsx, L3:L19.

-- Percentage values and thresholds use percentage points (85 means 85%).

-- Calendar rules and monthly limits are preserved in calc_extra; no DDL.

-- No ticket threshold is provided by the source; new ticket generation stays disabled.

SET @satisfaction_category = (SELECT id FROM metric_category WHERE category_code='satisfaction');

INSERT INTO metric_sub_category(category_id,sub_category_code,sub_category_name,status) SELECT @satisfaction_category,'sat_customer','客服投诉工单处理流程','enabled' WHERE @satisfaction_category IS NOT NULL ON DUPLICATE KEY UPDATE sub_category_name=VALUES(sub_category_name);

