INSERT INTO metric_monitor_config(metric_id,alarm_window_minutes,alarm_threshold,alarm_condition,alarm_status,gongdan_window_minutes,gongdan_status,consecutive_count)
SELECT id,1440,alarm_threshold,alarm_threshold_type,1,1440,0,1 FROM metric_item
WHERE category_id=@satisfaction_category AND calc_rule_type='satisfaction_report'
ON DUPLICATE KEY UPDATE alarm_threshold=VALUES(alarm_threshold),alarm_condition=VALUES(alarm_condition);

INSERT INTO alarm_strategy(strategy_name,strategy_type,target_type,target_id,target_name,alarm_enabled,alarm_threshold,alarm_condition,alarm_consecutive_times,gongdan_enabled,gongdan_consecutive_times,condition_type,threshold_value,consecutive_times,generate_type,status,create_time,update_time)
SELECT CONCAT(m.sub_category_name,'-',m.metric_name,'-预警'),'metric','metric',m.id,CONCAT(m.sub_category_name,'-',m.metric_name),1,c.alarm_threshold,c.alarm_condition,1,0,1,c.alarm_condition,c.alarm_threshold,1,'alarm',1,NOW(),NOW()
FROM metric_item m JOIN metric_monitor_config c ON c.metric_id=m.id
WHERE m.category_id=@satisfaction_category AND m.calc_rule_type='satisfaction_report'
AND NOT EXISTS(SELECT 1 FROM alarm_strategy s WHERE s.target_type='metric' AND s.strategy_type='metric' AND s.target_id=m.id);

UPDATE alarm_strategy s JOIN metric_item m ON s.target_type='metric' AND s.target_id=m.id
JOIN metric_monitor_config c ON c.metric_id=m.id
SET s.alarm_threshold=c.alarm_threshold,s.alarm_condition=c.alarm_condition
WHERE s.strategy_type='metric' AND m.category_id=@satisfaction_category AND m.calc_rule_type='satisfaction_report';

-- Repair the existing satisfaction health alarm's missing current fields using its own legacy values.
UPDATE alarm_strategy SET alarm_threshold=threshold_value,alarm_condition=condition_type
WHERE strategy_type='health' AND target_type='category' AND target_id=@satisfaction_category
AND alarm_threshold IS NULL AND threshold_value IS NOT NULL AND condition_type IN ('>','>=','<','<=','=');
INSERT INTO alarm_strategy(strategy_name,strategy_type,target_type,target_id,target_name,alarm_enabled,alarm_threshold,alarm_condition,alarm_consecutive_times,gongdan_enabled,status,create_time,update_time)
SELECT '满意度及投诉服务体验-健康度','health','category',id,category_name,1,80,'<',1,0,1,NOW(),NOW()
FROM metric_category c WHERE id=@satisfaction_category
AND NOT EXISTS(SELECT 1 FROM alarm_strategy s WHERE s.strategy_type='health' AND s.target_type='category' AND s.target_id=c.id);


